/*
 * A043469  Numbers having one 4 in base 9.
 * https://oeis.org/A043469
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   numbers having exactly one digit '4' when written in base 9. *
 *            The sequence is generated by scanning integers in increasing
 *            order and * selecting those whose base‑9 representation contains
 *            a single digit 4
 * Range:     u8 n <= 49, u16 n <= 50, u32 n <= 50, u64 n <= 50, u128 n <= 50,
 *            big any n
 * Validated: partial, pass, 50 terms through n = 50 (2026-11-01)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

static inline int count_digit4_uint64(uint64_t v)
{
    int cnt = 0;
    while (v) {
        int d = v % 9U;
        if (d == 4)
            ++cnt;
        if (cnt > 1)
            return 2;            /* early exit: more than one 4 */
        v /= 9U;
    }
    return cnt;
}

seq_t a(idx_t n)
{
    /* Offset starts at 1. For n == 0 behaviour is irrelevant. */
    idx_t target = n;
    idx_t count = 0U;
    idx_t candidate = 1U;

    while (1) {
        if (count_digit4_uint64((uint64_t)candidate) == 1) {
            ++count;
            if (count == target)
                return (seq_t)candidate;
        }
        ++candidate;
    }
}
